 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # In a horizontal marker row, recolor the trailing run after the marker
    # color changes to the background, using color 1.
    for row in out:
        marker = max(set(row), key=row.count)
        # Only rows that begin with a non-background color and then transition
        # to a different color have an encoded trailing segment.
        first = row[0]
        if first != marker:
            continue
        i = 0
        while i < len(row) and row[i] == first:
            i += 1
        if i < len(row) and all(x == marker for x in row[i:]):
            for j in range(i, len(row)):
                row[j] = 1
    return out
